REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(81000, 'zhCN', '升天之路：有趣的虚灵', '一群兴致勃勃的虚灵已在拍卖行内安顿下来，提供奇妙的货物与实用的服务。阿米尔·好运精通找回一切遗失之物并归还给你。马拉兹是外观与幻化的大师，能把从靴子到火球的一切都改头换面。提拉克西斯经营着虚空市集，提供库存有限的专属外观物品以及时序契约。与每一位虚灵交谈，浏览他们的货物与服务。', '与拍卖行内的虚灵交谈。', '', '与阿米尔·好运交谈
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(100466, 'zhCN', '升天之路：西部荒野', '向你致敬，英雄。$B$B欢迎来到联盟的首都暴风城。我想你是来休整补给吧。这里有许多能助你冒险的设施，从个人银行、拍卖行到铁匠、附魔师，当然还有其他英雄。你可以随意探索，但当你准备重返冒险时，就去找飞行管理员邓加·朗德瑞克吧。西部省份正有麻烦酝酿，需要你的援助。', '尽情探索暴风城，然后去找飞行管理员邓加·朗德瑞克飞往西部荒野，继续你的冒险。', '', '', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(149176, 'zhCN', '升天之路：大秘境商人', '埃德林·天歌对你的大秘境冒险十分感兴趣，他能在许多方面为你提供帮助。他会向你出售装备、协助你升级现有装备，并回收你不需要的大秘境物品以换取更多大秘境硬币，', '与沙塔斯的埃德林·天歌交谈', '', '与沙塔斯的埃德林·天歌交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(149179, 'zhCN', '升天之路：黑暗之门', '你直面燃烧军团的时刻已经到来。乘坐传送门前往诅咒之地，传送门位于暴风城法师区的法师塔顶。', '前往诅咒之地。', '', '使用诅咒之地传送门，并与守望堡指挥官雷索恩·奈瑟维交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(149180, 'zhCN', '升天之路：进入外域', '你直面燃烧军团的时刻已经到来。乘坐奥格瑞玛的传送门前往诅咒之地，传送门位于精神谷。', '前往诅咒之地。', '', '使用诅咒之地传送门，并与督军达图恩交谈。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(149181, 'zhCN', '升天之路：试炼与挑战', '石头塔克如坚定不移的哨兵，伫立在通向伟大的门槛前，他是试炼的守护者与仪典的主持者。试炼是可自定义的游戏模式，会深刻改变你的体验难度，并提供丰富多样的外观与装饰奖励。', '拜访试炼守护者石头塔克。', '', '与石头塔克交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(149182, 'zhCN', '升天之路：试炼与挑战', '石头塔克如坚定不移的哨兵，伫立在通向伟大的门槛前，他是试炼的守护者与仪典的主持者。试炼是可自定义的游戏模式，会深刻改变你的体验难度，并提供丰富多样的外观与装饰奖励。', '拜访试炼守护者石头塔克。', '', '与石头塔克交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(149183, 'zhCN', '升天之路：展翅高飞！', '你已在地面上证明了实力，但外域的天空正等待着你。若想翱翔于这片破碎之地，你需要相应的训练——以及一只飞行坐骑。去寻找影月谷的专家级飞行训练师吧，他们会指引你走上飞行之路。', '与影月谷的飞行教练奥尔罗克交谈。', '', '与影月谷的奥尔罗克交谈。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(149184, 'zhCN', '升天之路：展翅高飞！', '你已在地面上证明了实力，但外域的天空正等待着你。若想翱翔于这片破碎之地，你需要相应的训练——以及一只飞行坐骑。去寻找影月谷的专家级飞行训练师吧，他们会指引你走上飞行之路。', '与影月谷的飞行教练伊萨·雷酿交谈。', '', '与影月谷的飞行教练伊萨·雷酿交谈。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(149185, 'zhCN', '升天之路：神秘附魔品质', '神秘附魔按品质划分：稀有、史诗、传说与神器。这些附魔会强化法术、改变能力，或以不同方式提升属性，具体取决于其品质。', '为你的收藏添加 1 个各品质的附魔。', '', '收集稀有、史诗与传说品质的神秘附魔各一个。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(149186, 'zhCN', '升天之路：全副武装', '神秘附魔是你挖掘角色潜力的关键。因此你要确保已把收藏中能应用的附魔都装进激活附魔槽。在单一专精下你最多可激活 11 个神秘附魔：6 个稀有、3 个史诗、1 个传说和 1 个神器。', '在激活附魔界面中填满每一个空的神秘附魔槽位。', '', '用相应品质的附魔填满每一个激活槽位。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(149187, 'zhCN', '升天之路：激活神秘卷轴', '神秘附魔卷轴可通过击败敌人、在世界各处寻获，或与其他玩家交易获得。   获得后，前往神秘附魔祭坛应用神秘卷轴以获取其力量！神秘附魔祭坛常常被召唤在主城中，你也可以深入世界去寻访。它们的位置已标注在世界地图上。   神秘附魔是解锁你英雄力量的关键。找到能强化法术或开启全新流派的神秘附魔，以提升你的实力。', '- 通过击败敌人或与其他玩家交易获得神秘附魔卷轴。  - 与主城或野外的神秘附魔祭坛互动，选择“附魔卷轴”标签页。  - 激活神秘卷轴并将其应用到激活附魔槽位。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(149188, 'zhCN', '升天之路：重铸与神秘精华', '前往祭坛并选择“附魔卷轴”标签页，然后获取一张未磨损的神秘卷轴。  点击神秘卷轴上的“重铸”会为卷轴掷出新的神秘附魔，并覆盖卷轴上已有的附魔。重铸消耗神秘符文，若神秘符文用尽则消耗金币！  每次重铸都会为你累积神秘附魔等级的经验。每提升一级都会授予你一份神秘精华，可用于将神秘附魔永久存入你的附魔收藏。这份收藏在本服所有角色间共享！  神秘附魔祭坛常常被召唤在主城中，你也可以深入世界去寻访。它们的位置已标注在世界地图上。', '- 从神秘祭坛的“附魔卷轴”标签页获取一张未磨损的神秘卷轴。  - 重铸你的神秘卷轴以获得新的神秘附魔。你可以持续重铸任意神秘卷轴，直到找到想要保留的附魔。  - 重铸神秘卷轴会累积神秘精华的进度。  - 重铸 5 次。持续重铸，直到你获得一份神秘精华。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(149189, 'zhCN', '升天之路：神秘附魔收藏', '将神秘附魔存入收藏会为本服所有角色永久解锁它，之后你随时可以在祭坛应用该附魔，无需卷轴！  向收藏中添加附魔会销毁卷轴并消耗一份神秘精华。神秘精华的获取数量没有上限，所以务必保存你最喜爱的、以及对你的流派至关重要的神秘附魔。  从神秘祭坛的“卷轴”标签页选择一张神秘卷轴，然后点击“存入收藏”。', '从神秘祭坛的“卷轴”标签页选择一张神秘卷轴，然后点击“存入收藏”。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(189190, 'zhCN', '升天之路：使用你的神秘附魔收藏', '从神秘祭坛打开“附魔收藏”标签页，从你的附魔收藏中选择一个附魔并应用到激活附魔槽位，然后选择“保存更改”以激活你的神秘附魔。  从收藏中激活附魔需要神秘宝珠，可通过召集板的日常任务、地下城与团本、战场或击败野外敌人获得！  1 个传说附魔可应用于祭坛中央的大槽位。  3 个史诗附魔可应用于内圈的中等槽位。  其余槽位你可随意应用任意数量的稀有与优秀附魔。许多此类附魔最多可叠加 3 层。将鼠标悬停在收藏中的附魔上可查看其最大叠加层数。', '前往祭坛，将附魔收藏中的神秘附魔应用到激活附魔槽位。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580134, 'zhCN', '升天之路：重铸与神秘精华', '前往祭坛并选择“附魔卷轴”标签页，然后获取一张未磨损的神秘卷轴。  点击神秘卷轴上的“重铸”会为卷轴掷出新的神秘附魔，并覆盖卷轴上已有的附魔。重铸消耗神秘符文，若神秘符文用尽则消耗金币！  每次重铸都会为你累积神秘附魔等级的经验。每提升一级都会授予你一份神秘精华，可用于将神秘附魔永久存入你的附魔收藏。这份收藏在本服所有角色间共享！  神秘附魔祭坛常常被召唤在主城中，你也可以深入世界去寻访。它们的位置已标注在世界地图上。', '- 从神秘祭坛的“附魔卷轴”标签页获取一张未磨损的神秘卷轴。  - 重铸你的神秘卷轴以获得新的神秘附魔。你可以持续重铸任意神秘卷轴，直到找到想要保留的附魔。  - 重铸神秘卷轴会累积神秘精华的进度。  - 重铸 5 次。持续重铸，直到你获得一份神秘精华。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580135, 'zhCN', '升天之路：神秘附魔收藏', '将神秘附魔存入收藏会为本服所有角色永久解锁它，之后你随时可以在祭坛应用该附魔，无需卷轴！  向收藏中添加附魔会销毁卷轴并消耗一份神秘精华。神秘精华的获取数量没有上限，所以务必保存你最喜爱的、以及对你的流派至关重要的神秘附魔。  从神秘祭坛的“卷轴”标签页选择一张神秘卷轴，然后点击“存入收藏”。', '从神秘祭坛的“卷轴”标签页选择一张神秘卷轴，然后点击“存入收藏”。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580136, 'zhCN', '升天之路：外观藏品拍卖', '从拍卖行购买任意外观武器或护甲', '从拍卖行购买任意外观武器或护甲', '', '在“升天之路”中领取奖励。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580137, 'zhCN', '升天之路：收集幻化外观', '收集幻化外观', '收集幻化外观', '', '在“升天之路”中领取奖励。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580138, 'zhCN', '升天之路：终局流派', '满级流派远比练级流派强大。想在终局内容中取得成功，满级后升级你的流派至关重要。  你可以在英雄建筑师中找到许多已就绪的终局流派。按 N 键，点击英雄建筑师标签页，然后根据当前等级选择 60 级或 70 级流派。  你可以滚动浏览高评分的终局流派，找到契合自己玩法风格的那一套！  终局流派依赖神秘附魔。每套流派都会在流派页面底部显示所需的神秘附魔。你应立刻获取推荐的传说与史诗附魔，确保流派按预期运作，然后尽快集齐蓝色与绿色附魔。  强烈建议你在尝试自制终局流派前，先试用推荐流派。你也可以参考高评分流派来创建自己的流派，从而有一个扎实的基础。  一旦选定流派并逐渐得心应手，不要害怕尝试与调整，让它更贴合你的个人打法。', '打开英雄建筑师并载入一套 70 级流派。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580139, 'zhCN', '升天之路：PVE 强度', '通过装备灵魂绑定装备达到 460 点 PVE 强度', '通过装备灵魂绑定装备达到 460 点 PVE 强度', '', '在“升天之路”中领取奖励。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580140, 'zhCN', '升天之路：PVP 强度', '在每个装备槽位装备 PVP 或血铸装备，达到 250 点 PVP 强度。', '在每个装备槽位装备 PVP 或血铸装备，达到 250 点 PVP 强度。', '', '在“升天之路”中领取奖励。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580141, 'zhCN', '升天之路：武装起来！', '装备更强大的装备，达到 40 物品等级。', '装备更强大的装备，达到 40 物品等级。', '', '在“升天之路”中领取奖励。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580142, 'zhCN', '升天之路：史诗神秘附魔收藏', '将 3 个史诗附魔存入你的收藏。你可以重铸卷轴直到获得想要保存的史诗附魔，也可以在拍卖行搜索能强化你法术与天赋的附魔！  前往祭坛，从“卷轴”标签页选择一个史诗神秘卷轴，然后点击“存入收藏”。若你没有神秘精华，可在祭坛重铸神秘卷轴来获取。  史诗神秘附魔能为你的流派解锁惊人的力量。它们可以赋予全新的能力，并大幅强化你现有的能力。', '- 通过重铸、在世界中发现或从拍卖行获取史诗神秘附魔卷轴。  - 前往祭坛，将 3 个史诗神秘附魔存入你的附魔收藏。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580143, 'zhCN', '升天之路：传说神秘附魔收藏', '将一个传说附魔存入你的收藏。你可以重铸卷轴直到获得想要保存的传说附魔，也可以在拍卖行搜索能强化你法术与天赋的附魔！  前往祭坛，从“卷轴”标签页选择一个传说神秘卷轴，然后点击“存入收藏”。若你没有神秘精华，可在祭坛重铸神秘卷轴来获取。  传说神秘附魔能解锁改变格局的力量。它们可以开启全新的流派、彻底改变你的玩法，并为你的英雄带来巨幅战力提升。', '- 通过重铸、在世界中发现或从拍卖行获取传说神秘附魔卷轴。  - 前往祭坛，将一个传说神秘附魔存入你的附魔收藏。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580144, 'zhCN', '升天之路：地下城探索', '击败任意终局普通地下城的最终首领', '击败任意终局普通地下城的最终首领', '', '在“升天之路”中领取奖励。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580145, 'zhCN', '升天之路：英雄地下城', '完成任意英雄地下城', '完成任意英雄地下城', '', '在“升天之路”中领取奖励。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580146, 'zhCN', '升天之路：普通团本', '击败任意普通难度团本的最终首领', '击败任意普通难度团本的最终首领', '', '在“升天之路”中领取奖励。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580147, 'zhCN', '升天之路：史诗地下城', '打开地下城查找器，排队随机史诗地下城，或在“指定地下城”下选择任意一个可用的史诗地下城。  史诗地下城比英雄地下城更具挑战性。  在尝试史诗地下城之前，务必备齐完整的 PVE 装备并做好流派准备。  穿上你的 PVE 装备，击败任意史诗地下城的最终首领吧！', '击败任意史诗地下城的最终首领。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580148, 'zhCN', '升天之路：大秘境地下城', '大秘境地下城是你熟悉的地下城的计时版本，但另有玄机。  大秘境地下城中的生物、首领与普通小怪都可能被附加词缀强化，试图拖慢你的脚步。  你无法用地下城查找器排队进入大秘境，因此我们建议你在公会频道或世界频道招募队友。记得大秘境需要 1 名坦克、1 名治疗和 3 名输出。  要开启大秘境，队长必须让全队先前往该副本（建议使用回城石或头等舱实验型传送器）。  进入后，使用你的钥匙石开启地下城！', '完成任意大秘境地下城。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580149, 'zhCN', '升天之路：英雄团本', '击败任意英雄团本的最终首领', '击败任意英雄团本的最终首领', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580162, 'zhCN', '升天之路：升天难度团本', '击败任意升天难度团本的最终首领', '击败任意升天难度团本的最终首领', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580165, 'zhCN', '升天之路：战场！', '完成任意战场！', '完成任意战场！', '', '在“升天之路”中领取奖励。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580166, 'zhCN', '升天之路：2v2 单排', '你知道吗？不组队也能参加 2v2 对战。  在 Ascension，你随时可以与任何玩家匹配进行 2v2 战斗。  要参加任意 2v2 对战，打开 PVP 界面（H 快捷键）并点击竞技场下拉标签页。  选择 2v2 评级竞技场对战之后，你可以点击“加入战斗”进行单排。  我们的匹配系统会为你撮合当前最合适的队友，并把你送进一场 2v2 对战。', '使用单排功能加入一场 2v2 竞技场对战。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580167, 'zhCN', '升天之路：拜访竞技场商人', '拜访并查看任意竞技场商人的货物。', '拜访并查看任意竞技场商人的货物。', '', '在“升天之路”中领取奖励。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580168, 'zhCN', '升天之路：少跑路，多复活', '下次死亡时，在最近的城镇或城市安全复活！', '下次死亡时，在最近的城镇或城市安全复活！', '', '在“升天之路”中领取奖励。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580169, 'zhCN', '升天之路：神秘附魔收藏家', '收集神秘附魔、扩充你的附魔收藏，会给你更多选择与更强的力量。  你能存入附魔收藏的神秘附魔数量没有上限。你将通过重铸不断获得神秘精华，它可通过完成各类内容获取，也可以在召集板旁的诺兹多姆处用金币或升天印记购买。  将 10 个神秘附魔存入你的收藏。', '将 10 个神秘附魔存入你的附魔收藏。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580170, 'zhCN', '升天之路：中级骑术', '从骑术书或骑术训练师处学习中级骑术。', '从骑术书或骑术训练师处学习中级骑术。', '', '在“升天之路”中领取奖励。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580171, 'zhCN', '升天之路：第二专精', '学习第二专精。', '学习第二专精。', '', '在“升天之路”中领取奖励。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580172, 'zhCN', '升天之路：市集代币', '从拍卖行购买任意数量的市集代币。', '从拍卖行购买任意数量的市集代币。', '', '在“升天之路”中领取奖励。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580173, 'zhCN', '升天之路：虚空市集', '前往你阵营主城拍卖行的提拉克西斯处，查看虚空市集的商品。  虚空市集限量出售随机外观物品、法术与坐骑。提拉克西斯每天会从数千件外观物品中随机多次更新库存。在他那里总有新发现，你甚至可能成为第一个找到某件特定外观物品的玩家！  当提拉克西斯更新库存时，每件外观物品只有一名玩家能买到。你从提拉克西斯处购买某件物品后，在该物品再次被随机选入库存之前，其他人都无法获得它。  与提拉克西斯交谈，用市集代币购买任意物品。市集代币可从拍卖行获得！', '从虚空市集购买任意物品。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580174, 'zhCN', '升天之路：头等舱实验型传送器', '头等舱实验型传送器能让你从主城瞬间抵达世界各地或其他主城。  这台传送器位于主城的热门区域，外形醒目，你绝不会错过。  你会被抛到数百码的高空——别担心，我们会提供一顶降落伞，持续时间刚好够你……安全落地。', '使用头等舱实验型传送器。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580175, 'zhCN', '升天之路：战争游戏', '战争游戏是 Ascension 的一项功能，让你能排队进入任意战场或竞技场，代价是没有排队计时。  战争游戏让你可以免费测试自己的流派，在进入评级竞技场之前与朋友或对手交手，也让你的公会能与敌对公会一决高下。  要排队参加战争游戏，请在任意主城找到特里·格洛齐尔克。  找到你想对战的朋友或对手，选择战场或竞技场（我们推荐竞技场，适合小规模战斗），然后开始战斗。', '完成任意战争游戏。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580176, 'zhCN', '升天之路：泰坦卷轴', '使用任意泰坦卷轴。', '使用任意泰坦卷轴。', '', '在“升天之路”中领取奖励。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580179, 'zhCN', '升天之路：击杀世界首领', '击杀任意世界首领。', '击杀任意世界首领。', '', '在“升天之路”中领取奖励。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580181, 'zhCN', '升天之路：完成一次入侵', '入侵是周期性地在艾泽拉斯各处刷新的世界事件，其规模会根据区域内玩家数量动态调整。  要找到入侵，你可以查看世界地图，或在世界频道询问当前是否有入侵开启。  要完成入侵，你必须击杀最终首领。进入入侵后会出现一个完成度百分比计数器，当计数器达到 100% 时最终首领就会出现。', '击败入侵首领。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580182, 'zhCN', '升天之路：使用你的神秘附魔收藏', '从神秘祭坛打开“附魔收藏”标签页，从你的附魔收藏中选择一个附魔并应用到激活附魔槽位，然后选择“保存更改”以激活你的神秘附魔。  从收藏中激活附魔需要神秘宝珠，可通过召集板的日常任务、地下城与团本、战场或击败野外敌人获得！  1 个传说附魔可应用于祭坛中央的大槽位。  3 个史诗附魔可应用于内圈的中等槽位。  其余槽位你可随意应用任意数量的稀有与优秀附魔。许多此类附魔最多可叠加 3 层。将鼠标悬停在收藏中的附魔上可查看其最大叠加层数。', '前往祭坛，将附魔收藏中的神秘附魔应用到激活附魔槽位。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580183, 'zhCN', '升天之路：威望', '选择威望会将你的角色重置为 1 级，并将你传送到起始区域。  威望是获取装备、神秘附魔材料、升天印记等的绝佳途径！带着你已掌握的一切知识重新体验练级之旅、地下城与战场，包括你已保存的神秘附魔！  会发生什么：  - 你当前的专精会被重置。 - 你装备中的物品会邮寄给你。 - 所有练级任务会重置，可再次完成。 - 你的任务日志会被清空。  在通配模式下威望会重置你当前选择的专精！  你当前的通配专精将： - 遗忘所有法术与天赋。这会重置你的激活流派！ - 移除该专精的命运卷轴。 - 重置塞拉斯处该专精的命运卷轴任务。 - 移除命运之匣。 - 在达到满级前，其他所有专精将保持锁定。 - 你可以为威望后的专精激活新的技能卡。 - 你装备中的物品会邮寄给你。 - 所有练级任务会重置，可再次完成。 - 你的任务日志会被清空。  你将保留所有专业、装备、升天印记、货币与物品，但威望专精未使用的命运之手除外。若你已学习高级骑术，你将获得一本骑术书，可在相应等级重新学习骑术。', '如果你想威望转生，请与主城召集板旁的克罗米交谈。这会将你重置为 1 级！如果你不想威望，可以放弃此任务。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580184, 'zhCN', '升天之路：正义徽章', '完成任意英雄地下城', '完成任意英雄地下城', '', '在“升天之路”中领取奖励。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580186, 'zhCN', '升天之路：神秘附魔全满', '从神秘祭坛打开“附魔收藏”标签页，从你的附魔收藏中选择附魔，填满所有空的激活附魔槽位！若你无法填满全部 17 个激活附魔槽位，就去收集更多相关的神秘附魔。  从收藏中激活附魔需要神秘宝珠，可通过召集板的日常任务、地下城与团本、战场或击败野外敌人获得！  1 个传说附魔可应用于祭坛中央的大槽位。  3 个史诗附魔可应用于内圈的中等槽位。  其余槽位你可随意应用任意数量的稀有与优秀附魔。许多此类附魔最多可叠加 3 层。将鼠标悬停在收藏中的附魔上可查看其最大叠加层数。  填满全部 17 个激活附魔槽位！', '在全部 17 个激活附魔槽位中激活神秘附魔。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580187, 'zhCN', '升天之路：激活传说神秘附魔', '从神秘祭坛打开“附魔收藏”标签页，从你的附魔收藏中选择一个传说附魔并应用到中央的激活附魔槽位！   从收藏中激活附魔需要神秘宝珠，可通过召集板的日常任务、地下城与团本、战场或击败野外敌人获得！   你同一时间只能激活 1 个传说附魔。', '激活一个传说神秘附魔。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580188, 'zhCN', '升天之路：激活史诗神秘附魔', '从神秘祭坛打开“附魔收藏”标签页，从你的附魔收藏中选择史诗附魔并应用到 3 个史诗激活附魔槽位之一！   从收藏中激活附魔需要神秘宝珠，可通过召集板的日常任务、地下城与团本、战场或击败野外敌人获得！   你同一时间可以激活 3 个不同的史诗附魔。', '激活 3 个史诗神秘附魔。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580189, 'zhCN', '升天之路：神秘附魔专精', '你起初拥有 2 个神秘附魔专精。你可以在战斗之外随时免费切换附魔专精！    用专精之书解锁新专精时，也会解锁新的附魔专精。使用神秘附魔：专精之书可以解锁更多附魔专精！    神秘附魔专精让你能为激活附魔创建不同的配置。这使你可以：   - 随时更换附魔以尝试不同流派。   - 若你使用多专精玩不同流派，可维护不同的附魔配置。  - 针对特定场景与战斗进行调整。  - 在 PVE 与 PVP 附魔配置之间快速切换。', '- 从角色提升菜单打开你的附魔收藏，或使用祭坛。  - 点击左下角的“更改”按钮来更换你的附魔专精。  - 选择不同的专精，然后激活。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580190, 'zhCN', '升天之路：世界锻造附魔', '世界锻造神秘附魔无法交易，也无法在祭坛重铸时获得。这些灵魂绑定的神秘附魔必须去世界中发现！   获取一张世界锻造神秘附魔卷轴并存入你的收藏。', '将一个世界锻造神秘附魔法术存入你的附魔收藏。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580191, 'zhCN', '升天之路：凯旋印记', '凯旋印记可通过完成英雄与史诗难度地下城获得。   这些印记可以用来兑换装备！用它们升级你的装备，或攒起来换取对你的流派至关重要的特定装备。   前往暴风城王座厅的马库斯处，看看你能换到哪些装备。', '前往暴风城要塞并与马库斯交谈', '', '与暴风城王座厅的马库斯交谈。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580192, 'zhCN', '升天之路：凯旋印记', '凯旋印记可通过完成英雄与史诗难度地下城获得。   这些印记可以用来兑换装备！用它们升级你的装备，或攒起来换取对你的流派至关重要的特定装备。   前往奥格瑞玛，与智慧谷王座厅的玛尔托格交谈，看看你能换到哪些装备。', '前往奥格瑞玛的智慧谷并与玛尔托格交谈', '', '拜访奥格瑞玛智慧谷王座厅的玛尔托格。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580193, 'zhCN', '升天之路：神秘附魔全满', '从神秘祭坛打开“附魔收藏”标签页，从你的附魔收藏中选择附魔，填满所有空的激活附魔槽位！若你无法填满全部 17 个激活附魔槽位，就去收集更多相关的神秘附魔。  从收藏中激活附魔需要神秘宝珠，可通过召集板的日常任务、地下城与团本、战场或击败野外敌人获得！  通配英雄只能使用稀有与优秀附魔，且大多数最多可叠加 3 层！将鼠标悬停在收藏中的附魔上可查看其最大叠加层数。  用稀有与优秀附魔填满全部 17 个激活附魔槽位！', '在全部 17 个激活附魔槽位中激活神秘附魔。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580194, 'zhCN', '升天之路：神秘附魔收藏家', '收集神秘附魔、扩充你的附魔收藏，会给你更多选择与更强的力量。  你能存入附魔收藏的神秘附魔数量没有上限。你将通过重铸不断获得神秘精华，它可通过完成各类内容获取，也可以在召集板旁的诺兹多姆处用金币或升天印记购买。  将 10 个神秘附魔存入你的收藏。', '将 10 个神秘附魔存入你的附魔收藏。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580195, 'zhCN', '升天之路·通配：重掷法术', '在通配模式中习得的法术与能力可以用命运卷轴重掷！   塞拉斯·暗月每 10 级会免费赠送你命运卷轴，并在满级时以升天印记出售命运卷轴。   尽量重掷那些使用最少、且无法提升流派潜力的法术与能力。随着你不断重掷帮助最小的法术，你会获得越来越多能显著强化流派的法术。', '- 与主城的塞拉斯·暗月交谈以获取命运卷轴。  - 用 N 键或从菜单栏打开角色提升菜单。  - 点击你想要重掷的技能并选择“遗忘”。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580196, 'zhCN', '升天之路·通配：重掷天赋', '在通配模式中习得的天赋可以用命运卷轴：天赋与命运卷轴重掷！   塞拉斯·暗月每 10 级会免费赠送你命运卷轴，并在满级时以升天印记出售命运卷轴。   优先重掷那些不能直接提升实力或强化你常用能力的天赋！当你重掷掉最弱或最无关的天赋后，你的流派很快就会被能带来巨大提升的天赋填满。', '- 与主城的塞拉斯·暗月交谈以获取命运卷轴。  - 用 N 键或从菜单栏打开角色提升菜单。  - 点击你想要重掷的天赋并选择“遗忘”。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580197, 'zhCN', '升天之路·通配：锁定法术与天赋', '你可以锁定不想误操作遗忘或重掷的法术与天赋！这些随时可以解锁。   被锁定的法术与天赋还会排在最前面，这让你能快速找到要重掷的法术与天赋，并确保不会重掷你还没准备好的那些！   锁定机制既能保护你的流派，也让重掷更轻松。', '- 打开角色提升菜单  - 在你想要锁定的能力或天赋上选择锁定图标', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580198, 'zhCN', '升天之路·通配：技能卡包', '密封卡包含有满级天赋技能卡。  开启这些卡包可收集技能卡，用来更好地掌控未来的流派，或保证当前流派能拿到某些天赋。  从卡包中开出的卡片会自动加入你账号通用的技能卡收藏。', '- 拜访主城的塞拉斯·暗月 - 完成满级命运卷轴任务以获得密封卡包。 - 使用密封卡包将其开启。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580199, 'zhCN', '升天之路·通配：金色技能卡', '金色密封卡包含有金色技能卡！   金色技能卡包与金色卡的运作方式与普通技能卡相同，但它们可以填入金色技能卡槽位，让你在开始收集这些卡片后对流派有更强的掌控力。   开启普通技能卡包时也会周期性获得这类卡包，因为你开到的重复卡片会转化为免费卡包的进度。', '- 拜访主城的塞拉斯·暗月  - 选择金色技能卡菜单并购买一个金色卡包  - 使用你的金色密封卡包将其开启。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580200, 'zhCN', '升天之路·通配：暗月奖券', '开启密封卡包时你会获得暗月奖券。   这些奖券可在塞拉斯·暗月处兑换普通、优秀、稀有与史诗技能卡。攒下奖券，换取对你的流派至关重要的技能卡。   你还可以用暗月奖券购买外观奖品。暗月奖券袋可让你在账号内的其他角色之间转移暗月奖券。', '- 拜访主城的塞拉斯·暗月  - 选择暗月奖品菜单中的奖品  - 购买一个暗月奖券袋（25 张）', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580201, 'zhCN', '升天之路·通配：激活技能卡', '激活技能卡可保证你会掷出该法术或天赋。  技能卡只能在 1-9 级时激活。你可以随时向收藏中添加技能卡，且你的技能卡收藏在账号内所有角色之间共享。新建角色与威望后的角色都可以使用你已收集的卡片。  如果你使用多个专精，你可以在某个专精中使用技能卡，直到该专精掷出它的第 5 个法术为止。', '- 打开角色提升界面 - 点击技能卡标签页 - 在 1-9 级时激活一张技能卡。', '', '返回召集板。', NULL);
